(function(){'use strict';const R=CritterRenderer.prototype,{WEAPONS}=Critters,decor=R.decorations,event=R.event;
R.event=function(e){event.call(this,e);if(e.type==='fire'&&[3,8,13,14].includes(e.weapon)){const u=this.game.active;this.rings.push({x:u.x,y:u.y,r:e.weapon===14?220:60,life:.7,max:.7});if(e.weapon===14)this.shake=this.reduced?0:23;}};
R.decorations=function(k,back){decor.call(this,k,back);if(back||this.lobby)return;for(const t of this.game.graves||[]){k.save();k.translate(t.x,t.y+18);k.fillStyle='#172b3640';k.beginPath();k.ellipse(0,0,22,6,0,0,7);k.fill();k.fillStyle=t.team?'#b99c9d':'#9daeb6';k.strokeStyle='#3b4c59';k.lineWidth=2;k.beginPath();k.moveTo(-15,0);k.lineTo(-15,-24);k.quadraticCurveTo(-15,-43,0,-43);k.quadraticCurveTo(15,-43,15,-24);k.lineTo(15,0);k.closePath();k.fill();k.stroke();k.fillStyle='#dce2d7';k.fillRect(-3,-34,6,18);k.fillRect(-9,-29,18,5);k.fillStyle='#405264';k.font='bold 8px sans-serif';k.textAlign='center';k.fillText('R.I.P.',0,-6);k.fillStyle='#e7d6b1';k.fillRect(-20,-3,40,5);k.restore();}};
R.projectile=function(k){for(const p of [this.game.projectile,...(this.game.salvos||[])].filter(Boolean)){const w=WEAPONS[p.weapon],id=p.weapon,trail=p.trail||[];k.save();k.lineCap='round';for(let i=1;i<trail.length;i++){k.globalAlpha=i/trail.length*.7;k.strokeStyle=w.color;k.lineWidth=id===12?3:id===15?5:2;k.beginPath();k.moveTo(trail[i-1].x,trail[i-1].y);k.lineTo(trail[i].x,trail[i].y);k.stroke();}k.globalAlpha=1;k.translate(p.x,p.y);k.rotate(w.fuse?p.age*3:Math.atan2(p.vy,p.vx));k.strokeStyle='#293e4d';k.lineWidth=1.6;k.fillStyle=w.color;
const oval=(x,y,rx,ry)=>{k.beginPath();k.ellipse(x,y,rx,ry,0,0,7);k.fill();k.stroke();};
const rocket=(size,color)=>{k.fillStyle=color;k.beginPath();k.moveTo(size,0);k.lineTo(0,-size*.4);k.lineTo(-size,-size*.4);k.lineTo(-size*.65,0);k.lineTo(-size,size*.4);k.lineTo(0,size*.4);k.closePath();k.fill();k.stroke();k.fillStyle='#ffb265';k.beginPath();k.moveTo(-size*.7,-3);k.lineTo(-size*1.8-(Math.sin(p.age*60)+1)*4,0);k.lineTo(-size*.7,3);k.fill();};
if(id===0){rocket(12,'#e8cf95');k.fillStyle='#cf6a5b';k.fillRect(-5,-5,4,10);}
else if(id===1){oval(0,0,10,13);k.strokeStyle='#38573d';for(let y=-7;y<=7;y+=7){k.beginPath();k.moveTo(-8,y);k.lineTo(8,y);k.stroke();}k.fillStyle='#ced3a2';k.fillRect(-3,-17,6,6);}
else if(id===2){rocket(16,'#869da9');k.fillStyle='#e8a361';k.fillRect(-8,-6,5,12);}
else if(id===4){if(p.child){oval(0,0,5,5);}else{oval(0,0,13,13);k.fillStyle='#6d5a49';for(let i=0;i<5;i++){const a=i*Math.PI*.4;k.beginPath();k.arc(Math.cos(a)*7,Math.sin(a)*7,3,0,7);k.fill();}}}
else if(id===5){k.fillStyle='#c5d8dc';k.beginPath();k.moveTo(17,0);k.lineTo(-8,-7);k.lineTo(-8,7);k.closePath();k.fill();k.stroke();k.strokeStyle='#5b7786';for(let x=-6;x<10;x+=4){k.beginPath();k.moveTo(x,-5+x*.2);k.lineTo(x+4,4-x*.2);k.stroke();}}
else if(id===6){k.fillStyle='#ffc795';oval(0,0,7,5);k.fillStyle='#a9634b';k.fillRect(-6,-3,4,6);}
else if(id===7){k.beginPath();for(let i=0;i<12;i++){const a=i*Math.PI/6,r=i%2?9:14;k.lineTo(Math.cos(a)*r,Math.sin(a)*r);}k.closePath();k.fill();k.stroke();k.fillStyle='#fff0d9';oval(0,0,4,4);}
else if(id===9){k.shadowColor='#ffe794';k.shadowBlur=16;oval(0,0,15,15);k.shadowBlur=0;k.fillStyle='#fff7d1';k.fillRect(-3,-12,6,24);k.fillRect(-11,-5,22,6);k.strokeStyle='#fceaae';k.beginPath();k.arc(0,0,22,0,7);k.stroke();}
else if(id===10){rocket(13,'#e998a4');k.fillStyle='#ffdf8a';oval(4,0,7,6);}
else if(id===11){if(p.child){k.scale(.65,.65);}k.fillStyle='#f5d358';k.beginPath();k.moveTo(-17,-10);k.quadraticCurveTo(-2,5,17,-10);k.quadraticCurveTo(5,23,-13,5);k.closePath();k.fill();k.stroke();k.fillStyle='#7a985a';k.fillRect(-18,-13,5,7);}
else if(id===12){k.shadowColor='#a5deff';k.shadowBlur=14;k.fillStyle='#dff6ff';k.fillRect(-20,-2,36,4);k.shadowBlur=0;k.fillStyle='#78c1ed';k.fillRect(-12,-4,8,8);}
else if(id===15){k.rotate(p.age*5);k.shadowColor='#cbb0ff';k.shadowBlur=20;k.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,r=i%2?8:19;k.lineTo(Math.cos(a)*r,Math.sin(a)*r);}k.closePath();k.fill();k.stroke();k.shadowBlur=0;k.fillStyle='#f5edff';oval(0,0,5,5);}
else rocket(10,w.color);k.restore();
if(w.fuse&&!p.child&&!p.preview){k.save();k.fillStyle='#142f42e8';this.round(k,p.x-18,p.y-36,36,18,5);k.fill();k.fillStyle=w.color;k.font='bold 11px monospace';k.textAlign='center';k.fillText(Math.max(0,w.fuse-p.age).toFixed(1)+'s',p.x,p.y-23);k.restore();}
}};
const oldWeapon=R.weapon;R.weapon=function(k,id,x,y,s=1){if(id<4)return oldWeapon.call(this,k,id,x,y,s);k.save();k.translate(x,y);k.scale(s*1.3,s*1.3);if([8,13,14].includes(id)){k.strokeStyle=WEAPONS[id].color;k.fillStyle='#244452';k.lineWidth=3;if(id===8){for(let i=0;i<3;i++){k.beginPath();k.ellipse(0,0,9+i*7,18+i*3,0,0,7);k.stroke();}}else if(id===13){k.beginPath();k.moveTo(0,-23);k.lineTo(19,-13);k.lineTo(14,9);k.lineTo(0,23);k.lineTo(-14,9);k.lineTo(-19,-13);k.closePath();k.fill();k.stroke();k.fillStyle='#a5e9ce';k.fillRect(-2,-11,4,20);k.fillRect(-9,-4,18,4);}else {k.fillRect(-22,-16,44,32);k.strokeRect(-22,-16,44,32);k.beginPath();k.moveTo(-17,0);k.lineTo(-8,0);k.lineTo(-3,-10);k.lineTo(2,12);k.lineTo(8,-6);k.lineTo(13,0);k.lineTo(18,0);k.stroke();}}else R.projectile.call({game:{projectile:{x:0,y:0,weapon:id,age:0,vx:1,vy:0,trail:[],preview:true},salvos:[]}},k);k.restore();};
})();
